#include <check.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    struct {
        char *dir;
    } *inf;
} ak_doc;

#define AK_PATH_BUFFER_SIZE 4096

#define ak_path_full(DEST, DOC, FILE_NAME)                                \
  do {                                                                    \
    strcpy(DEST, DOC->inf->dir);                                          \
    strcat(DEST, "/");                                                    \
    strcat(DEST, FILE_NAME);                                              \
  } while(0)

